import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { ApiService } from '../api.service';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="container">
      <div class="card" style="max-width: 400px; margin: 50px auto;">
        <h2 style="text-align: center; color: #2196F3; margin-bottom: 30px;">SmartOptions</h2>

        <div *ngIf="error" class="alert alert-danger">{{ error }}</div>

        <form (ngSubmit)="onLogin()">
          <div class="form-group">
            <label>Username:</label>
            <input type="text" class="form-control" [(ngModel)]="credentials.username" name="username" required>
          </div>

          <div class="form-group">
            <label>Password:</label>
            <input type="password" class="form-control" [(ngModel)]="credentials.password" name="password" required>
          </div>

          <button type="submit" class="btn" style="width: 100%;" [disabled]="loading">
            {{ loading ? 'Logging in...' : 'Login' }}
          </button>
        </form>

        <div style="text-align: center; margin-top: 20px;">
          <p>Demo credentials: admin / (set password via admin panel)</p>
        </div>
      </div>
    </div>
  `
})
export class LoginComponent {
  credentials = { username: '', password: '' };
  loading = false;
  error = '';

  constructor(private apiService: ApiService, private router: Router) {}

  onLogin() {
    this.loading = true;
    this.error = '';

    this.apiService.login(this.credentials).subscribe({
      next: (response) => {
        this.apiService.setToken(response.access);
        this.router.navigate(['/dashboard']);
      },
      error: (error) => {
        this.error = 'Invalid credentials';
        this.loading = false;
      }
    });
  }
}
